,p_name=>'PE.PROPERTY.CACHE_CONDITION_SQL_STATEMENT.EXAMPLES'
,p_message_language=>'pt-br'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<dl><dt>Para retornar valores com sucesso quando uma ou mais linhas existirem ao verificar se o funcion\00E1rio est\00E1 no departamento 30:</dt>'),
'<dd><pre>',
'select 1',
'  from emp',
' where empno  = :P2_EMPNO',
'   and deptno = 30',
'</pre></dd>',
unistr('<dt>Para retornar valores com sucesso quando n\00E3o existirem linhas ao verificar se o funcion\00E1rio est\00E1 no departamento 40:</dt>'),
'<dd><pre>',
'select 1',
'  from emp',
' where empno  = :P2_EMPNO',
'   and deptno = 40',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2565617
);
