,p_name=>'PE.PROPERTY.DOM_STATIC_ID.COMPONENT_PROPERTY.BUTTON.HELP'
,p_message_language=>'pt-br'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('Informe o ID do est\00E1tico para o bot\00E3o. Se definido, o ID est\00E1tico ser\00E1 usado como o ID do bot\00E3o. O ID est\00E1tica pode ser \00FAtil ao desenvolver o comportamento JavaScript personalizado para o bot\00E3o. Se o ID est\00E1tico n\00E3o for definido, o bot\00E3o gerar\00E1 um ID')
||' interno.',
unistr('<p>Observa\00E7\00E3o: O modelo deve incluir a string de substitui\00E7\00E3o <code>#BUTTON_ID#</code> para que ele possa usar o ID est\00E1tico especificado.</p>')))
,p_version_scn=>2565528
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(116045671302665806)
,p_name=>'PE.PROPERTY.DOM_STATIC_ID.COMPONENT_PROPERTY.IG_COLUMN.HELP'
,p_message_language=>'pt-br'
,p_message_text=>unistr('Informe o ID est\00E1tico da coluna. O ID est\00E1tico pode ser \00FAtil ao desenvolver o comportamento de JavaScript personalizado, ou o estilo personalizado da coluna. Se o ID est\00E1tico n\00E3o for definido, o ID interno ser\00E1 usado para o ID do item da coluna.')
,p_version_scn=>2565528
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(116045539270665806)
,p_name=>'PE.PROPERTY.DOM_STATIC_ID.COMPONENT_PROPERTY.IR_COLUMN.HELP'
,p_message_language=>'pt-br'
,p_message_text=>unistr('Informe o ID est\00E1tico da coluna. Se definido, o ID est\00E1tico \00E9 usado como o ID da c\00E9lula TH (cabe\00E7alho de tabela) correspondente e como o valor HEADERS das c\00E9lulas TD (dados de tabela) correspondentes. O ID est\00E1tico pode ser \00FAtil ao desenvolver o comp')
||unistr('ortamento de JavaScript personalizado, ou o estilo personalizado da coluna. Se o ID est\00E1tico n\00E3o for definido, a tabela gerar\00E1 um ID interno para esses valores de atributo.')
,p_version_scn=>2565528
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(116045461370665806)
,p_name=>'PE.PROPERTY.DOM_STATIC_ID.COMPONENT_PROPERTY.REGION.HELP'
