,p_message_language=>'pt-br'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<dl>',
'  <dt>Alterar as cores do plano de fundo e do texto</dt>',
'    <dd><pre>&lt;span style="background-color:yellow; color:red;">#EMPLOYEE_STATUS#&lt;/span></pre></dd>',
unistr('  <dt>Usar Cabe\00E7alho 2</dt>'),
'    <dd><pre>&lt;h2>#EMPLOYEE_NAME#&lt;/h2></pre></dd>',
unistr('  <dt>Usar uma classe din\00E2mica da consulta SQL</dt>'),
'    <dd><pre>&lt;span class="#COLUMN_CLASS#">#EMPLOYEE_STATUS#&lt;/span></pre><br>',
unistr('    As substitui\00E7\00F5es <code>#COLUMN_CLASS#</code> e <code>#EMPLOYEE_STATUS#</code> nesse exemplo s\00E3o colunas selecionadas na consulta SQL do relat\00F3rio.</dd>'),
unistr('  <dt>Mostrar uma imagem e uma dica de ferramenta ao passar o mouse sobre a op\00E7\00E3o</dt>'),
'    <dd><pre>&lt;img src="#IMAGE_NAME#" title="#EMPLOYEE_NAME#"&gt;</pre></dd>',
unistr('  <dt>Repetir uma lista de valores separados por v\00EDrgulas</dt>'),
'    <dd><pre>&lt;ul>{loop "," TAGS/}&lt;li>&APEX$ITEM.&lt;/li>{endloop/}&lt;/ul></pre></dd>',
'  <dt>Usar uma diretiva "if" para uma coluna com identificador entre aspas</dt>',
'    <dd><pre>{if Mixed Case Name/}&lt;strong>#"Mixed Case Name"#&lt;/strong>{endif/}</pre></dd>',
'</dl>'))
,p_version_scn=>2565700
);
