wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(116850844557666043)
,p_name=>'PE.PROPERTY.ICON_VIEW_CUSTOM.HELP'
,p_message_language=>'pt-br'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Digite o HTML da coluna personalizada para a View de \00CDcone.</p>'),
unistr('<p>As seguintes strings de substitui\00E7\00E3o est\00E3o dispon\00EDveis:'),
'<ul>',
unistr('<li><code>&&lt;COLUMN_NAME&gt;.</code> - strings de substitui\00E7\00E3o para nomes de coluna.</li>'),
unistr('<li><code>&&lt;COLUMN_NAME&gt;_LABEL.</code> - strings de substitui\00E7\00E3o para labels de coluna.</li>'),
'<li><code>&APEX$ROW_ID.</code> - o identificador de registro para a linha.</li>',
unistr('<li><code>&APEX$ROW_INDEX.</code> - o n\00FAmero de sequ\00EAncia de exibi\00E7\00E3o de registro.</li>'),
unistr('<li><code>&APEX$ROW_URL.</code> - refer\00EAncia ao Destino do Link especificado.</li>'),
'<li><code>&APEX$ROW_STATE_CLASSES.</code> - o estado do registro, como <code>is-inserted</code> ou <code>is-deleted</code>.</li>',
'</ul>',
'</p>'))
,p_version_scn=>2565651
);
