,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'<dl>',
unistr('<dt>Uma lista delimitada por v\00EDrgulas que cont\00E9m valores num\00E9ricos est\00E1ticos:</dt>'),
'<dd><pre>',
'<strong>5,10,15</strong>',
'</pre></dd>',
unistr('<dt>Uma lista delimitada por v\00EDrgulas que cont\00E9m itens de p\00E1gina ou de aplicativo e que retorna valores num\00E9ricos, usando:</dt>'),
'<dd><pre>',
'a sintaxe <code>&amp;ITEM.</code>. Por exemplo, <strong><code>&amp;ITEM_1.</code>,<code>&amp;ITEM_2.</code>,<code>&amp;ITEM_3.</code></strong>',
'</pre></dd>',
unistr('<dt>Uma lista delimitada por v\00EDrgulas que cont\00E9m colunas e retorna valores num\00E9ricos, usando:</dt>'),
'<dd><pre>',
'a sintaxe <code>&amp;COLUMN_NAME.</code>. Por exemplo, <strong><code>&amp;COLUMN_NAME_1.</code>,<code>&amp;COLUMN_NAME_2.</code>,<code>&amp;COLUMN_NAME_3.</code></strong>',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2565528
);
