wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(117465097916666225)
,p_name=>'PE.PROPERTY.TITLE.COMPONENT_PROPERTY.JET_CHART_AXES.HELP'
,p_message_language=>'pt-br'
,p_message_text=>unistr('Informe um t\00EDtulo para o eixo. Esse t\00EDtulo descreve as informa\00E7\00F5es que est\00E3o sendo representadas no eixo do seu gr\00E1fico.')
,p_version_scn=>2565755
