wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(117012334931666091)
,p_name=>'PE.PROPERTY.USE_CUSTOM_ICON_VIEW.HELP'
,p_message_language=>'pt-br'
,p_message_text=>unistr('Especifique se voc\00EA deseja definir um link personalizado para a View de \00CDcone. Esta op\00E7\00E3o oferece uma maior flexibilidade na defini\00E7\00E3o do conte\00FAdo da View de \00CDcone, incluindo a capacidade de utilizar mais de uma coluna.')
