wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(116069421660665813)
,p_name=>'USER_TYPE_DESCRIPTION'
,p_message_language=>'pt-br'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Use esta p\00E1gina para controlar o acesso dos administradores de espa\00E7os de trabalho, desenvolvedores de aplicativos e usu\00E1rios finais do Oracle APEX.</p>'),
'',
unistr('<p><strong>Administradores de espa\00E7os de trabalho</strong> podem criar e modificar aplicativos e objetos de banco de dados, assim como gerenciar contas de usu\00E1rio, grupos e servi\00E7os de desenvolvimento.</p>'),
'',
'<p><strong>Desenvolvedores</strong> podem criar e modificar aplicativos e objetos de banco de dados.</p>',
'',
unistr('<p><strong>Usu\00E1rios finais</strong> n\00E3o t\00EAm privil\00E9gios de desenvolvimento e s\00F3 podem acessar aplicativos que n\00E3o usam um esquema de autentica\00E7\00E3o externo.</p>'),
'',
'<p><a target="_blank" href="%0/aeadm/managing-users-in-a-workspace.html">Saiba Mais...</a></p>',
''))
,p_version_scn=>2565531
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(116090539050665819)
,p_name=>'USER_TYPE_DESCRIPTION_CLOUD'
,p_message_language=>'pt-br'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Utilize esta p\00E1gina para controlar o acesso dos usu\00E1rios finais ao Oracle APEX.<p>'),
'',
unistr('Os <p><strong>usu\00E1rios finais</strong> n\00E3o t\00EAm privil\00E9gios de desenvolvimento e s\00F3 podem acessar aplicativos que n\00E3o utilizam um esquema de autentica\00E7\00E3o externo.</p>'),
'',
unistr('Os <p><strong>administradores de espa\00E7os de trabalho</strong> e os <strong>desenvolvedores</strong> s\00E3o gerenciados com a Console de Identidades. Sempre que um administrador de espa\00E7os de trabalho ou um desenvolvedor faz log-in no APEX, uma conta "so')
||unistr('mbra" \00E9 criada. Esses usu\00E1rios "sombras" podem ser removidos, se necess\00E1rio.</p>')))
,p_version_scn=>2565535
);
