wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(117478058651666229)
,p_name=>'UTR.HELP.P1'
,p_message_language=>'pt-br'
,p_message_text=>unistr('O Rolador de Tema permite f\00E1cil personaliza\00E7\00E3o da interface do usu\00E1rio do seu aplicativo, possibilitando a voc\00EA selecionar cores e definir estilos para v\00E1rios componentes de aplicativo. Um aplicativo pode ter qualquer n\00FAmero de estilos de tema defini')
||unistr('do; entretanto, somente o estilo ''Atual'' \00E9 usado para exibir o aplicativo para os usu\00E1rios finais.')
,p_is_js_message=>true
,p_version_scn=>2565758
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(117478164634666229)
,p_name=>'UTR.HELP.P2'
,p_message_language=>'pt-br'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('Depois de fazer altera\00E7\00F5es, os atributos podem ser restaurados facilmente, para o estilo de tema completo pressionando o bot\00E3o Redefinir ou pressionando o \00EDcone de redefini\00E7\00E3o do grupo. '),
'',
unistr('No caso de atributos que permitem a sele\00E7\00E3o de cores de primeiro plano e plano de fundo, a caixa de sele\00E7\00E3o que vem antes das duas sele\00E7\00F5es de cores indica informa\00E7\00F5es de contraste de cores com base nas diretrizes WCAG (Web Content Accessibility Guid')
||unistr('elines) 2.0. Uma pontua\00E7\00E3o de contraste calculada mais alta indica que a combina\00E7\00E3o de cores \00E9 mais acess\00EDvel.')))
,p_is_js_message=>true
,p_version_scn=>2565758
);
