wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(116075346032665814)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION1'
,p_message_language=>'pt-br'
,p_message_text=>unistr('A fun\00E7\00E3o de sentinela de p\00E1gina retornar\00E1 o resultado booleano da verifica\00E7\00E3o de sess\00E3o incorporada ao mecanismo. Se o resultado for verdadeiro, o mecanismo continuar\00E1 a mostrar ou aceitar a p\00E1gina. Se for falso, o mecanismo redirecionar\00E1 para o URL ')
||unistr('ou p\00E1gina de sess\00E3o inv\00E1lida especificados no esquema de autentica\00E7\00E3o (veja a seguir).')
,p_version_scn=>2565533
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(116076679188665815)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION10'
,p_message_language=>'pt-br'
,p_message_text=>unistr('Se a fun\00E7\00E3o de sentinela de p\00E1gina retornar TRUE, a convers\00E3o ou o processamento da p\00E1gina continuar\00E1. Se o resultado for FALSE, o mecanismo dever\00E1 ser encerrado, pois n\00E3o h\00E1 um destino de sess\00E3o inv\00E1lida especificado no esquema de autentica\00E7\00E3o. Ness')
||unistr('e caso, sup\00F5e-se que a fun\00E7\00E3o de sentinela de p\00E1gina fornecida pelo usu\00E1rio redirecionou para uma p\00E1gina de log-in fora do ambiente %0, possivelmente um portal com autentica\00E7\00E3o externa. A fun\00E7\00E3o tamb\00E9m deve ter definido a vari\00E1vel global g_unrecovera')
||unistr('ble_error := true para instruir o mecanismo a encerrar sem mostrar uma p\00E1gina de erro.')
,p_version_scn=>2565533
);
