unistr(' where name = :<em>nome do item de p\00E1gina</em>;'),
'</pre>',
unistr('<p>Para acessar arquivos se a op\00E7\00E3o <strong>Permitir V\00E1rios Arquivos</strong> estiver definida como <strong>Sim</strong>:</p>'),
'<pre>',
'declare',
'    l_file_names apex_t_varchar2;',
'    l_file       apex_application_temp_files%rowtype;',
'begin',
'    l_file_names := apex_string.split (',
unistr('                        p_str => :<em>nome do item de p\00E1gina</em>,'),
'    for i in 1 .. l_file_names.count loop',
'        select *',
'          into l_file',
'          from apex_application_temp_files',
'         where name = l_file_names(i);',
'        -- add code here to store the uploaded file in your own table',
'    end loop;',
'end;',
'</pre>'))
);
