,p_help_text=>unistr('Em geral, os servi\00E7os REST do Oracle Cloud Applications (BOSS) suportam a recupera\00E7\00E3o de resultados uma p\00E1gina por vez. No entanto, se o ponto final dessa origem de dados n\00E3o suportar o par\00E2metro "$offset", defina essa propriedade como N\00E3o para desat')
||unistr('ivar a pagina\00E7\00E3o.')
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(31645891650179321.4416)
,p_plugin_id=>wwv_flow_imp.id(3240013576755763.4416)
