wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(23296341939280297.4416)
,p_plugin_id=>wwv_flow_imp.id(23280737050223902.4416)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>4
,p_display_sequence=>10
,p_prompt=>unistr('Endere\00E7o Estruturado')
,p_attribute_type=>'CHECKBOX'
,p_is_required=>false
,p_default_value=>'Y'
,p_is_translatable=>false
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Indica se as partes de endere\00E7o s\00E3o fornecidas ao servi\00E7o de geocodifica\00E7\00E3o de modo <em>estruturado</em> ou <em>n\00E3o estruturado</em>.</p>'),
unistr('<p>Estruturado significa que itens de p\00E1gina expl\00EDcitos s\00E3o mapeados para partes de endere\00E7o como Rua, C\00F3digo Postal, Cidade ou Regi\00E3o. Isso leva a resultados de geocodifica\00E7\00E3o mais precisos, e tamb\00E9m permite alimentar os '),
unistr('endere\00E7os corrigidos de volta aos itens de p\00E1gina.</p>'),
unistr('<p>N\00E3o estruturado significa que apenas um item \00E9 usado para todo o endere\00E7o; as partes s\00E3o separadas por v\00EDrgulas. Esse modo n\00E3o permite alimentar endere\00E7os corrigidos de volta ao item de p\00E1gina.</p>')))
);
wwv_flow_imp_shared.create_plugin_attribute(
