wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(23299513762315037.4416)
,p_plugin_id=>wwv_flow_imp.id(23280737050223902.4416)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>14
,p_display_sequence=>140
,p_prompt=>unistr('Item de Vetor de Correspond\00EAncia')
,p_attribute_type=>'PAGE ITEM'
,p_is_required=>false
,p_is_translatable=>false
,p_attribute_group_id=>wwv_flow_imp.id(6274942011526119)
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Selecione um item de p\00E1gina para armazenar o <em>Vetor de Correspond\00EAncia</em> da <em>primeira correspond\00EAncia do Geocodificador</em>. O vetor de correspond\00EAncia \00E9 uma string de 17 d\00EDgitos com informa\00E7\00F5es detalhadas sobre como cada atributo de end')
||unistr('ere\00E7o foi correlacionado com os dados usados para geocodifica\00E7\00E3o.</p>'),
unistr('<p><strong>Os d\00EDgitos do Vetor de Correspond\00EAncia podem ter os seguintes valores:</strong></p>'),
'<ul>',
unistr('<li><p>0: O atributo de entrada n\00E3o \00E9 nulo e corresponde a um valor n\00E3o nulo.</p></li>'),
unistr('<li><p>1: O atributo de entrada \00E9 nulo e \00E9 corresponde a um valor nulo.</p></li>'),
unistr('<li><p>2: O atributo de entrada n\00E3o \00E9 nulo e \00E9 substitu\00EDdo por outro valor n\00E3o nulo.</p></li>'),
unistr('<li><p>3: O atributo de entrada n\00E3o \00E9 nulo e \00E9 substitu\00EDdo por um valor nulo.</p></li>'),
unistr('<li><p>4: O atributo de entrada \00E9 nulo e \00E9 substitu\00EDdo por um valor n\00E3o nulo.</p></li>'),
'</ul>',
'<br>',
unistr('<p><strong>D\00EDgitos do Vetor de Correspond\00EAncia e o atributo de endere\00E7o correspondente a cada um:</strong></p>'),
'<ul>',
unistr('<li><p>3: Ponto de Endere\00E7o (endere\00E7o exato correspondido nos dados usados para geocodifica\00E7\00E3o)</p></li>'),
'<li><p>4: Nome do Ponto de Interesse</p></li>',
unistr('<li><p>5: N\00FAmero da Casa</p></li>'),
'<li><p>6: Prefixo da Rua</p></li>',
'<li><p>7: Nome da Rua</p></li>',
'<li><p>8: Sufixo da Rua</p></li>',
'<li><p>9: Tipo de Rua</p></li>',
unistr('<li><p>10: Unidade Secund\00E1ria</p></li>'),
'<li><p>11: Cidade</p></li>',
unistr('<li><p>14: Regi\00E3o</p></li>'),
unistr('<li><p>15: Pa\00EDs</p></li>'),
unistr('<li><p>16: C\00F3digo Postal</p></li>'),
unistr('<li><p>17: C\00F3digo Postal Suplementar</p></li>'),
unistr('<li><p><em>outros d\00EDgitos ainda n\00E3o s\00E3o utilizados.</em></p></li>'),
'</ul>'))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(23312282210252045.4416)
,p_plugin_id=>wwv_flow_imp.id(23280737050223902.4416)
