,p_is_required=>true
,p_display_length=>40
,p_is_translatable=>false
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('Informe o padr\00E3o usado para construir a string de nome distinto (DN) completo para DBMS_LDAP.SIMPLE_BIND_S, se estiver usando DN exato, ou a base de pesquisa, se estiver usando DN n\00E3o exato. Utilize <strong>%LDAP_USER%</strong> como marcador para o n')
||unistr('ome do usu\00E1rio. Por exemplo:'),
'<p>',
'<strong>DN Exato</strong>',
'</p>',
'<p>',
'cn=%LDAP_USER%,l=amer,dc=yourdomain,dc=com',
'</p>',
'<p>',
unistr('<strong>DN N\00E3o-Exato (Base de Pesquisa)</strong>'),
'</p>',
'<p>',
'dc=yourdomain,dc=com',
'</p>'))
);
wwv_flow_imp_shared.create_plugin_attribute(
