,p_api_version=>3
,p_standard_attributes=>'VISIBLE:SESSION_STATE:READONLY:ESCAPE_OUTPUT:SOURCE:ELEMENT:ELEMENT_OPTION:ENCRYPT:LOV:CASCADING_LOV:JOIN_LOV:FILTER:LINK:FC_HAS_FEEDBACK:FC_SHOW_SELECTED_FIRST:FC_SHOW_MORE_COUNT:FC_FILTER_VALUES:FC_LOV_DISPLAY_NULL:MULTI_VALUE_ALWAYS'
,p_substitute_attributes=>true
,p_version_scn=>7414340
,p_subscribe_plugin_settings=>true
,p_is_quick_pick=>true
,p_help_text=>unistr('Exibe v\00E1rios valores como caixas de sele\00E7\00E3o, permitindo que o usu\00E1rio final selecione diversos valores. \00C9 necess\00E1ria uma lista de valores para itens exibidos como caixas de sele\00E7\00E3o. Os valores correspondentes \00E0s caixas de sele\00E7\00E3o marcadas s\00E3o armazen')
||unistr('adas em uma \00FAnica string delimitado por dois pontos.')
);
