,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_static_id=>'number_of_columns'
,p_prompt=>unistr('N\00FAmero de Colunas')
,p_attribute_type=>'INTEGER'
,p_is_required=>true
,p_default_value=>'1'
,p_display_length=>3
,p_max_length=>3
,p_supported_component_types=>'APEX_APPLICATION_PAGE_ITEMS:APEX_APPL_PAGE_IG_COLUMNS'
,p_is_translatable=>false
,p_help_text=>unistr('Informe o n\00FAmero de colunas de layout usadas para exibir as caixas de sele\00E7\00E3o. Por exemplo, um valor 2 exibir\00E1 duas colunas de caixas de sele\00E7\00E3o. Por padr\00E3o, todos os valores exibidos em uma coluna.')
);
