 p_id=>wwv_flow_imp.id(845156526173834547.4416)
,p_plugin_id=>wwv_flow_imp.id(2693981597889753854.4416)
,p_name=>'LOV'
,p_sql_min_column_count=>2
,p_depending_on_has_to_exist=>true
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<dl>',
'<dt>Lista de valores baseada na consulta SQL</dt>',
'<dd><pre>',
'select ename as d, ',
'       empno as r',
'  from emp ',
' order by 1',
'</pre></dd>',
unistr('<dt>Lista de valores com o mesmo valor de exibi\00E7\00E3o e de retorno</dt>'),
'<dd><pre>',
'select ename d,',
'       ename r ',
'  from emp ',
' order by 1',
'</pre>',
unistr('<p>Observa\00E7\00E3o: Ao selecionar a mesma coluna para os valores de exibi\00E7\00E3o e de retorno use um alias de coluna.</p>'),
'</dd>',
unistr('<dt>Lista de valores com vari\00E1vel de bind</dt>'),
'<dd><pre>',
'select ename,',
'       empno ',
'  from emp ',
' where deptno = :P3_DEPTNO ',
' order by 1',
'</pre>',
unistr('<p>Observa\00E7\00E3o: Defina o atributo <em>Item(ns) Principal(s) da LOV em Cascata</em> como <code>P3_DEPTNO</code> se <code>P3_DEPTNO</code> for um item de p\00E1gina modific\00E1vel da mesma p\00E1gina.</dd>'),
'</dl>'))
);
